def mark_legacy_expired_rows(apps, _schema_editor):
    """Give already-cleaned legacy EXPIRED rows their data marker.

    The legacy cleanup emptied these rows before this migration, so the
    marker is technical metadata, not a new decision. A row that still
    keeps bank payload is left unmarked on purpose: hiding retained
    details would be worse than reporting them.
    """
    rows = apps.get_model('users', 'BankStatementRow')
    observed_at = timezone.now()
    candidates = rows.objects.filter(
        decision='expired',
        data_cleaned_at__isnull=True,
        transaction_type__isnull=True,
        transaction_date__isnull=True,
        amount__isnull=True,
        description='',
        candidate_description='',
        suggested_category='',
        merchant_key='',
        counterparty_account='',
        source_ref__isnull=True,
        candidate__isnull=True,
    ).select_related('upload')
    for row in candidates.iterator():
        row.data_cleaned_at = row.upload.retention_cleaned_at or observed_at
        row.save(update_fields=['data_cleaned_at'])


